// DOM rendering. Takes data as arguments, never reads app state.
import { allTags, computeKpis, filterTasks, isOverdue, uniqueOwners } from "./rules.js";
import { escapeHtml, formatBody } from "./format.js";

export function renderKpis(tasks, notes) {
  const k = computeKpis(tasks, notes);
  document.getElementById("kpi-open").textContent = k.open;
  document.getElementById("kpi-done").textContent = k.done;
  document.getElementById("kpi-overdue").textContent = k.overdue;
  document.getElementById("kpi-notes").textContent = k.notes;
}

export function renderOwnerFilter(tasks) {
  const select = document.getElementById("owner-filter");
  const current = select.value;
  select.innerHTML = '<option value="">All owners</option>' +
    uniqueOwners(tasks).map((o) => `<option value="${escapeHtml(o)}">${escapeHtml(o)}</option>`).join("");
  select.value = current;
}

export function renderTasks(tasks, filters) {
  const rows = filterTasks(tasks, filters);
  const body = document.getElementById("tasks-body");
  body.innerHTML = rows.map((t) => `
    <tr class="${isOverdue(t) ? "overdue" : ""}">
      <td>${escapeHtml(t.title)}</td>
      <td>${escapeHtml(t.owner || "–")}</td>
      <td>${escapeHtml(t.due || "–")}</td>
      <td><span class="status status-${t.status}">${t.status}</span></td>
    </tr>`).join("");
  document.getElementById("tasks-empty").hidden = rows.length > 0;
}

export function renderTags(notes, activeTag, onToggle) {
  const box = document.getElementById("tag-chips");
  box.innerHTML = allTags(notes).map((tag) =>
    `<button class="chip ${tag === activeTag ? "active" : ""}" data-tag="${escapeHtml(tag)}">#${escapeHtml(tag)}</button>`).join("");
  box.querySelectorAll(".chip").forEach((chip) => chip.addEventListener("click", () => onToggle(chip.dataset.tag)));
}

export function renderNotes(notes) {
  const list = document.getElementById("notes-list");
  list.innerHTML = notes.map((n) => `
    <li>
      <h3>${escapeHtml(n.title)}</h3>
      <p>${formatBody(n.body)}</p>
      <div class="note-tags">${(n.tags || []).map((t) => `<span>#${escapeHtml(t)}</span>`).join("")}</div>
    </li>`).join("");
  document.getElementById("notes-empty").hidden = notes.length > 0;
}

export function renderLastUpdated() {
  document.getElementById("last-updated").textContent = `updated ${new Date().toLocaleTimeString()}`;
}

