// Shipyard release dashboard entry point: state, event wiring and startup.
import { fetchNotes, fetchTasks } from "./api.js";
import {
  renderKpis, renderLastUpdated, renderNotes, renderOwnerFilter, renderTags, renderTasks,
} from "./render.js";

const state = { tasks: [], notes: [], owner: "", status: "pending", q: "", tag: "" };

async function reloadNotes() {
  state.notes = await fetchNotes(state);
  renderNotes(state.notes);
  renderTagChips();
  renderKpis(state.tasks, state.notes);
}

function renderTagChips() {
  renderTags(state.notes, state.tag, async (tag) => {
    state.tag = state.tag === tag ? "" : tag;
    await reloadNotes();
  });
}

function renderAll() {
  renderKpis(state.tasks, state.notes);
  renderOwnerFilter(state.tasks);
  renderTasks(state.tasks, state);
  renderTagChips();
  renderNotes(state.notes);
  renderLastUpdated();
}

async function init() {
  document.getElementById("owner-filter").addEventListener("change", (e) => {
    state.owner = e.target.value;
    renderTasks(state.tasks, state);
  });
  document.getElementById("status-filter").addEventListener("change", (e) => {
    state.status = e.target.value;
    renderTasks(state.tasks, state);
  });
  let timer;
  document.getElementById("notes-search").addEventListener("input", (e) => {
    clearTimeout(timer);
    timer = setTimeout(async () => {
      state.q = e.target.value.trim();
      await reloadNotes();
    }, 200);
  });
  [state.tasks, state.notes] = await Promise.all([fetchTasks(), fetchNotes(state)]);
  renderAll();
}

if (typeof document !== "undefined") init();

