import test from "node:test";
import assert from "node:assert/strict";
import { fetchNotes, fetchTasks } from "../api.js";
import { formatBody } from "../format.js";

function stubFetch(response) {
  const urls = [];
  globalThis.fetch = async (url) => {
    urls.push(url);
    return response;
  };
  return urls;
}

const ok = (data) => ({ ok: true, status: 200, json: async () => data });
const quiet = () => { console.error = () => {}; };

test("fetchTasks calls /api/tasks and returns the parsed list", async () => {
  const urls = stubFetch(ok([{ id: 1 }]));
  assert.deepEqual(await fetchTasks(), [{ id: 1 }]);
  assert.deepEqual(urls, ["/api/tasks"]);
});

test("fetchNotes sends q and tag only when set", async () => {
  let urls = stubFetch(ok([]));
  await fetchNotes({ q: "api", tag: "ops" });
  await fetchNotes({});
  assert.deepEqual(urls, ["/api/notes?q=api&tag=ops", "/api/notes?"]);
});

test("failed requests fall back to an empty list", async () => {
  const original = console.error;
  quiet();
  try {
    stubFetch({ ok: false, status: 500 });
    assert.deepEqual(await fetchTasks(), []);
    assert.deepEqual(await fetchNotes({}), []);
  } finally {
    console.error = original;
  }
});

test("formatBody turns **bold** into strong tags", () => {
  assert.equal(formatBody("a **b** c"), "a <strong>b</strong> c");
});

